CREATE TABLE cmdb_ire_manual_overrides (tenant_id BIGINT UNSIGNED NOT NULL, ci_id BIGINT UNSIGNED NOT NULL, field_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, override_type ENUM('TEMPORARY','PERMANENT') NOT NULL, reason VARCHAR(500) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), expires_at DATETIME(6) NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,ci_id,field_key), KEY cmdb_ire_override_expiry(tenant_id,expires_at), CONSTRAINT cmdb_ire_override_ci FOREIGN KEY(tenant_id,ci_id) REFERENCES cmdb_cis(tenant_id,id) ON DELETE CASCADE, CONSTRAINT cmdb_ire_override_user FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT cmdb_ire_override_expiry CHECK((override_type='PERMANENT' AND expires_at IS NULL) OR (override_type='TEMPORARY' AND expires_at IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
